def simulate_snake(board_size, snake, food, moves):
    """
    Simulate a snake moving on a rectangular board.

    Returns:
        (final_snake, alive, food_eaten)
    """

    width, height = board_size

    if width <= 0 or height <= 0:
        raise ValueError("board dimensions must be positive")

    snake = [tuple(segment) for segment in snake]
    food = [tuple(position) for position in food]

    def in_bounds(position):
        x, y = position
        return 0 <= x < width and 0 <= y < height

    if not snake:
        raise ValueError("snake must contain at least one segment")

    if any(not in_bounds(position) for position in snake):
        raise ValueError("all snake coordinates must be inside the board")

    if len(set(snake)) != len(snake):
        raise ValueError("snake segments may not overlap")

    if any(not in_bounds(position) for position in food):
        raise ValueError("all food coordinates must be inside the board")

    directions = {
        "UP": (0, -1),
        "DOWN": (0, 1),
        "LEFT": (-1, 0),
        "RIGHT": (1, 0),
    }

    opposite = {
        "UP": "DOWN",
        "DOWN": "UP",
        "LEFT": "RIGHT",
        "RIGHT": "LEFT",
    }

    # Infer the initial movement direction from the head and neck.
    current_direction = None
    if len(snake) >= 2:
        dx = snake[0][0] - snake[1][0]
        dy = snake[0][1] - snake[1][1]

        for name, vector in directions.items():
            if vector == (dx, dy):
                current_direction = name
                break

        if current_direction is None:
            raise ValueError("the snake's head and neck must be adjacent")

    food_index = 0
    food_eaten = 0
    alive = True

    for requested_direction in moves:
        if requested_direction not in directions:
            raise ValueError(f"invalid move: {requested_direction}")

        # A snake cannot reverse directly into itself.
        if (
            current_direction is not None
            and requested_direction == opposite[current_direction]
        ):
            applied_direction = current_direction
        else:
            applied_direction = requested_direction

        dx, dy = directions[applied_direction]
        head_x, head_y = snake[0]
        new_head = (head_x + dx, head_y + dy)

        if not in_bounds(new_head):
            alive = False
            break

        # The snake grows only when it reaches the currently active food.
        growing = (
            food_index < len(food)
            and new_head == food[food_index]
        )

        # On a non-growing move, the tail is about to leave its cell,
        # so moving into that specific cell is allowed.
        body_to_check = snake[1:]
        if not growing:
            body_to_check = body_to_check[:-1]

        if new_head in body_to_check:
            alive = False
            break

        if growing:
            snake = [new_head] + snake
            food_index += 1
            food_eaten += 1
        else:
            snake = [new_head] + snake[:-1]

        current_direction = applied_direction

    return snake, alive, food_eaten
